import React from "react";
import headerBg from '../img/header-bg.png'; 

const Home = () => {
  return (
    <div
      style={{
        boxSizing: "border-box",
        margin: 0,
        padding: 0,
        width: "100vw",
        height: "100vh",        // теперь блок занимает весь экран
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center", // центрирование по вертикали
        gap: "20px",
        textAlign: "center",
      }}
    >
      <h1>Hi, my name is <strong>John Doe</strong></h1>
      <h2>a frontend developer</h2>
      <h3>with passion for learning and creating.</h3>

      <img
        src={headerBg} 
        alt="Profile"
        style={{ width: "200px" }} 
      />

      <a href="CV.pdf" target="_blank" rel="noopener noreferrer">
        <button
          style={{
            width: "150px",
            height: "40px",
            fontSize: "16px",
            cursor: "pointer",
            backgroundColor: "#4CAF50",
            color: "white",
            border: "none",
          }}
        >
          Download CV
        </button>
      </a>
    </div>
  );
};

export default Home;
